Lemma bytes_at_read : forall m a bs (k : Z) n,
  bytes_at m a bs ->
  (0 <= k)%Z -> (Z.to_nat k + n <= length bs)%nat ->
  ov_read_bytes segs m (wa (a + k)) n = Some (firstn n (skipn (Z.to_nat k) bs)).
