  (0 <= a)%Z -> (a + Z.of_nat (length bs) <= 2^64)%Z ->
  write_to_mem m (wa a) bs x =
    if (Z.leb a (bv_unsigned x) && Z.ltb (bv_unsigned x) (a + Z.of_nat (length bs)))%bool
    then nth_error bs (Z.to_nat (bv_unsigned x - a))
    else m x.
