Lemma bytes_at_write_inside : forall m c cs (k : Z) bs,
  bytes_at m c cs ->
  (0 <= k)%Z -> (Z.to_nat k + length bs <= length cs)%nat ->
  bytes_at (write_to_mem m (wa (c + k)) bs) c (upd_bytes cs (Z.to_nat k) bs).
Proof.
