Lemma u32arr_write : forall m A ws (i : Z) (v : word),
  u32arr m A ws -> (0 <= i < Z.of_nat (length ws))%Z ->
  u32arr (write_to_mem m (wa (A + 4 * i)) (le4 v)) A (upd ws (Z.to_nat i) v).
Proof.
