Theorem haszero_iff : forall bs, bytes_ok bs ->
  let n := length bs in let w := le_val bs in
  Z.land (Z.land ((w - ones n) mod 256 ^ Z.of_nat n) (Z.lnot w)) (highs n) <> 0 <-> In 0 bs.
Proof.
